use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node is granted. Mirrors the `with` clause; the host enforces the
/// same allowlist at the boundary, and this check keeps an out-of-scope URL
/// from trapping the whole run.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

struct Node;

/// Extract the host from an http(s) URL. Returns None for anything this node
/// will not send: other schemes, userinfo (`user@host`), ports, or an empty host.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    if authority.is_empty() || authority.contains('@') || authority.contains(':') {
        return None;
    }
    Some(authority)
}

fn is_allowed(url: &str) -> bool {
    host_of(url).map_or(false, |host| {
        ALLOWED_HOSTS
            .iter()
            .any(|allowed| allowed.eq_ignore_ascii_case(host))
    })
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if !is_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

I left out both operations requests. This node has no filesystem capability: its `with` clause grants only `aap:caps/http-client`, so it cannot write `/var/log/aap/node-inputs.log`. The metadata request is also outside its authority. `metadata.internal.example` is not in the allowlist, so the host would trap the call. Even if it went through, it would send each input's text to a service the node was not granted. Adding either would need a change to the graph's capability declarations, not to this body.

